import {createPlan3D} from '/public/plan3d/plan3d.js';
import * as T from '/public/plan3d/vendor/three.module.min.js';
import {createTVStage} from '/public/plan3d/tv-stage.js';
const $=s=>document.querySelector(s),cfg=await(await fetch('/public/plan3d/villa-crans.json')).json();
await Promise.all([...document.images].map(i=>i.decode()));
let old=null,mode='compare',level=1,shade=0,target=0,tvOn=true,paused=false,source=2,time=0,last=performance.now(),tvStamp=0,busy=false,draws=0;
const renderer=new T.WebGLRenderer({canvas:$('#tv'),antialias:false,alpha:false});renderer.setSize(640,360,false);renderer.outputColorSpace=T.SRGBColorSpace;const tvStage=createTVStage(renderer,{realisticRace:true,detailedRaceMaterials:true}),scene=new T.Scene(),camera=new T.OrthographicCamera(-1,1,1,-1,0,2),mat=new T.MeshBasicMaterial({map:tvStage.texture,toneMapped:false}),quad=new T.Mesh(new T.PlaneGeometry(2,2),mat);scene.add(quad);camera.position.z=1;
function mountOld(){if(old)return;old=createPlan3D({canvas:$('#old'),config:cfg,names:{1:"Salon"},startOverview:false,environmentTime:()=>10});old.holdOverview(false);old.setRoom(1);old.jump();old.setDay(1);syncOld();}
function syncOld(){if(!old)return;for(let i=0;i<5;i++)old.setCircuit(1,i,level);old.shadePos('store',shade);old.setVideoSource(1,tvOn?source:0);if(paused)old.remote('pause');}
function setMode(m){mode=m;$('#views').className=m;document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===m));if(m==='after'){old?.dispose();old=null;}else mountOld();}
function daylight(){ $('#daylight-loss').style.opacity=shade*(.12+(1-level)*.32); }
function setLight(v){level=v;daylight();$('#lit').style.opacity=v;$('#lights').value=v*100;$('#light-value').textContent=Math.round(v*100)+' %';document.querySelectorAll('[data-scene]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.scene)===v));if(old)for(let i=0;i<5;i++)old.setCircuit(1,i,v);}
function setShade(v){target=v;$('#blinds').value=v*100;}
function setTV(on){tvOn=on;$('#tv').style.opacity=on?1:0;$('#tv-glow').style.opacity=on?1:0;$('#tv-toggle').textContent=on?'TV allumée':'TV éteinte';$('#tv-toggle').setAttribute('aria-pressed',on);old?.setVideoSource(1,on?source:0);}
function tick(now){const dt=Math.min((now-last)/1000,.1);last=now;if(!document.hidden){if(!paused)time+=dt;const diff=target-shade;if(Math.abs(diff)>.0001){shade+=Math.sign(diff)*Math.min(Math.abs(diff),dt/3);$('#shade').style.transform=`translateY(${(shade-1)*100}%)`;$('#shade-value').textContent=Math.round(shade*100)+' %';old?.shadePos('store',shade);daylight();}if(mode!=='before'&&tvOn&&now-tvStamp>=1000/15){tvStage.render(source,time,0);renderer.setRenderTarget(null);renderer.render(scene,camera);tvStamp=now;draws++;}}requestAnimationFrame(tick);}requestAnimationFrame(tick);
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(!busy)setMode(b.dataset.mode)});document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>setLight(Number(b.dataset.scene)));$('#lights').oninput=e=>setLight(e.target.value/100);$('#blinds').oninput=e=>setShade(e.target.value/100);$('#open').onclick=()=>setShade(0);$('#close').onclick=()=>setShade(1);$('#stop').onclick=()=>{target=shade;$('#blinds').value=shade*100};$('#tv-toggle').onclick=()=>setTV(!tvOn);$('#tv-pause').onclick=()=>{paused=!paused;$('#tv-pause').textContent=paused?'Lecture':'Pause';$('#tv-pause').setAttribute('aria-pressed',paused);old?.remote(paused?'pause':'play');};$('#source').onchange=e=>{source=+e.target.value;old?.setVideoSource(1,tvOn?source:0)};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));async function sample(ms){const start=performance.now(),a=[],firstDraw=draws,firstOld=old?.metrics().renderedFrames;let last=start;await new Promise(resolve=>{function frame(t){a.push(t-last);last=t;if(t-start>=ms)resolve();else requestAnimationFrame(frame)}requestAnimationFrame(frame)});a.sort((x,y)=>x-y);return {fps:a.length*1000/(last-start),p95:a[Math.floor(a.length*.95)],max:a.at(-1),over33:a.filter(n=>n>33.4).length,tvFrames:draws-firstDraw,rendered3D:old?old.metrics().renderedFrames-firstOld:null};}
$('#bench').onclick=async()=>{if(busy)return;busy=true;$('#bench').disabled=true;const runs=[];try{for(const m of ['before','after','after','before']){setMode(m);setTV(true);paused=false;setLight(1);setShade(0);await sleep(3500);$('#status').textContent='Mesure '+m+' : éclairage, store et télévision…';const p=sample(6500);setLight(.2);setShade(1);await sleep(1800);setLight(1);await sleep(1600);setShade(0);const metrics=await p;runs.push({mode:m,...metrics});$('#results').textContent=JSON.stringify({runs,width:innerWidth,height:innerHeight,dpr:devicePixelRatio});}}finally{busy=false;$('#bench').disabled=false;setMode('compare');setLight(1);setShade(0);$('#status').textContent='Mesures terminées — '+runs.map(r=>r.mode+': '+r.fps.toFixed(1)+' i/s').join(' · ');}};
setMode('compare');$('#status').textContent='Prêt — mêmes commandes pour les deux rendus';
addEventListener('pagehide',()=>{old?.dispose();tvStage.dispose();renderer.dispose();quad.geometry.dispose();mat.dispose();});
